JS=r'''
/* 칸 ① 쪽지 가르기 */
var CARDS=[['거래처는 파랑상사예요','s','무엇이 어떠한지를 말해요. 바뀌면 고쳐 써야 해요.'],['지난번 견적서는 표를 먼저 보여 줬더니 바로 승인받았어요','e','그때 이렇게 했더니 이렇게 됐다는 말이에요. 비슷한 일에 본보기로 써요.'],['글은 존댓말로 써 주세요','p','앞으로 어떻게 하라는 말이에요. 모든 답에 늘 적용해요.'],
 ['예산 한도는 오백만 원이에요','s','한도가 얼마인지라는 사실이에요.'],['긴 설명을 보냈더니 요점만 달라는 답이 왔어요','e','겪은 일이에요. 거듭되면 “요점만 쓰기”라는 규칙이 될 수 있어요.'],['답은 세 줄 안으로 해 주세요','p','일하는 방식에 대한 규칙이에요.'],
 ['커피는 디카페인만 마셔요','s','손님에 관한 사실이에요.'],['출장 기차표를 전날 끊으려다 매진돼서 곤란했어요','e','겪은 일이에요. 다음 출장 때 “미리 끊자”는 본보기가 돼요.'],['숫자는 표로 정리해 주세요','p','앞으로 지킬 방식이에요.']];
var NAMES={s:'사실',e:'경험',p:'하는 법'},ci=0,right=0,done=false;
function showCard(){if(ci>=CARDS.length){$('#cgCard').textContent=tpl('아홉 장을 다 갈랐어요. 처음에 맞힌 것은 {0}장이에요.',right);$('#cgProg').textContent='끝';$$('#cgBtns button').forEach(function(b){b.disabled=true;});return;}
  $('#cgCard').textContent='“'+CARDS[ci][0]+'”';$('#cgProg').textContent=tpl('{0} / 9번째 쪽지',ci+1);done=false;}
$$('#cgBtns button').forEach(function(b){b.addEventListener('click',function(){var c=CARDS[ci],fb=$('#cgFb');if(!c)return;
  if(b.dataset.v===c[1]){if(!done)right++;fb.className='fb ok';fb.textContent=tpl('맞아요. {0}이에요. {1}',NAMES[c[1]],c[2]);ci++;setTimeout(showCard,REDUCE?0:900);}
  else{done=true;fb.className='fb no';fb.textContent='다시 생각해 보세요. 이 말은 언제 쓰일까요? 찾아볼 때, 비슷한 일을 할 때, 아니면 늘?';}});});
showCard();
/* 칸 ② */
var NW=15,cv2=$('#c2'),TOT=12,ALL=120;
function got(n){return TOT*(1-Math.exp(-n/14));}
function prf(n){var u=got(n),p=u/n,r=u/TOT;return {u:u,p:p,r:r,f:2*p*r/(p+r)};}
var BEST=4;for(var q=5;q<=ALL;q++)if(prf(q).f>prf(BEST).f)BEST=q;
function upd2(){var z=prf(NW);
  kpis($('#k2'),[[NW+'장','적은 쪽지','a'],[f2(z.u,1)+'개','건진 쓸모 있는 말 (12개 가운데)','i'],[f2(z.p*100,0)+'%','정밀도 (쪽지 가운데 쓸모 있는 비율)',z.p>0.4?'g':'r'],[f2(z.r*100,0)+'%','재현율 (쓸모 있는 말 가운데 건진 비율)',z.r>0.6?'g':'r']]);
  $('#ins2').innerHTML=(NW<8?'<p class="r">너무 적게 적었어요. 서랍은 깨끗하지만 필요한 말 대부분이 없어요.</p>':(NW>50?tpl('<p class="r">너무 많이 적었어요. 서랍의 {0}%가 쓸모없는 쪽지예요. 찾을 때 걸리적거려요.</p>',f2((1-z.p)*100,0)):'<p class="g">두 비율이 모두 볼 만한 구간이에요.</p>'))+tpl('<p>두 비율의 조화평균은 {0}점이에요. 이 모형에서 가장 높은 곳은 {1}장({2}점)이에요.</p>',f2(z.f*100,0),BEST,f2(prf(BEST).f*100,0));drawAll();}
bindRange('r2N',function(v){NW=v;upd2();},function(v){return v+'장';});
addMod(cv2,function(){var H=270,W=fit(cv2,H),ctx=cv2.getContext('2d');ctx.clearRect(0,0,W,H);var p=[],r=[],f=[];for(var i=4;i<=ALL;i++){var z=prf(i);p.push(z.p);r.push(z.r);f.push(z.f);}
  plot(ctx,W,H,{x0:4,x1:ALL,y0:0,y1:1.05,yn:4,yfmt:function(v){return Math.round(v*100)+'%';},xticks:[4,12,30,60,90,120],xlab:function(v){return v+'장';},lines:[{d:r,x0:4,color:COL.info,w:2},{d:p,x0:4,color:COL.eye,w:2},{d:f,x0:4,color:COL.gfp,w:2.4}],legend:[['재현율',COL.info],['정밀도',COL.eye],['조화평균',COL.gfp]],marks:[{x:NW,color:COL.amber,label:NW+'장'}]});stamp(ctx,W,'설명용 모형');});
PAGE._T={u15:got(15),p15:prf(15).p,r15:prf(15).r,f15:prf(15).f,f120:prf(120).f,p120:prf(120).p,best:BEST,fb:prf(BEST).f};
/* 대결 */
Duel({el:'#duel',higherIsBetter:true,drawMargin:0.05,fmt:function(v){return f2(v,0)+'점';},run:function(){return {fly:prf(15).f*100,robo:prf(120).f*100,metric:'조화평균'};},
  say:function(f,b){return tpl('조화평균은 초파리 쪽 15장이 {0}점, 주판봇 쪽 120장이 {1}점이에요. 15장은 정밀도 {2}%·재현율 {3}%, 120장은 정밀도 10%·재현율 100%예요.',f2(f,0),f2(b,0),f2(prf(15).p*100,0),f2(prf(15).r*100,0));},
  lessons:{F:'전부 적은 서랍은 아무것도 고르지 않은 서랍이다. 가려 적어야 쓸 수 있다',D:'둘이 비슷했다',R:'전부 적은 쪽이 앞섰다'},
  after:function(){$('#duelNote').innerHTML=tpl('<p>이 모형에서 조화평균이 가장 높은 곳은 {0}장({1}점)이에요. 쓸모 있는 말의 수(12개)를 조금 넘는 장수예요.</p><p>틀리면 큰일 나는 일이라면 재현율을 더 무겁게 쳐야 해요. 그때는 많이 적고, 대신 찾는 법을 더 좋게 만드는 쪽으로 가요.</p>',BEST,f2(prf(BEST).f*100,0));}});
upd2();
'''
